package com.ehtid.screentranslator;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.hardware.display.*;
import android.media.*;
import android.media.projection.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import com.google.mlkit.vision.common.InputImage;
import com.google.mlkit.vision.text.*;
import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
import com.google.mlkit.vision.text.chinese.ChineseTextRecognizerOptions;
import com.google.mlkit.vision.text.japanese.JapaneseTextRecognizerOptions;
import com.google.mlkit.vision.text.korean.KoreanTextRecognizerOptions;
import com.google.mlkit.nl.languageid.*;
import com.google.mlkit.nl.translate.*;
import java.nio.ByteBuffer;
import java.util.*;
public class CaptureService extends Service {
 WindowManager wm; LinearLayout overlay; TextView output; MediaProjection projection; VirtualDisplay display; ImageReader reader; Handler handler=new Handler(Looper.getMainLooper()); boolean busy=false,auto=false; int width,height,density; final List<TextRecognizer> recognizers=new ArrayList<>(); Translator translator; String translatorLang="";
 @Override public void onCreate(){super.onCreate();NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("capture","Экранный перевод",NotificationManager.IMPORTANCE_LOW));Notification n=new Notification.Builder(this,"capture").setContentTitle("EHTID Translator активен").setSmallIcon(android.R.drawable.ic_menu_search).build();startForeground(1,n,android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);wm=getSystemService(WindowManager.class);recognizers.add(TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS));recognizers.add(TextRecognition.getClient(new ChineseTextRecognizerOptions.Builder().build()));recognizers.add(TextRecognition.getClient(new JapaneseTextRecognizerOptions.Builder().build()));recognizers.add(TextRecognition.getClient(new KoreanTextRecognizerOptions.Builder().build()));createOverlay();}
 @Override public int onStartCommand(Intent i,int f,int id){if(i==null)return START_NOT_STICKY;Intent data=android.os.Build.VERSION.SDK_INT>=33?i.getParcelableExtra("data",Intent.class):i.getParcelableExtra("data");if(data==null)return START_NOT_STICKY;MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);projection=m.getMediaProjection(i.getIntExtra("result",-1),data);if(projection==null)return START_NOT_STICKY;projection.registerCallback(new MediaProjection.Callback(){@Override public void onStop(){stopSelf();}},handler);android.util.DisplayMetrics dm=getResources().getDisplayMetrics();width=dm.widthPixels;height=dm.heightPixels;density=dm.densityDpi;reader=ImageReader.newInstance(width,height,android.graphics.PixelFormat.RGBA_8888,2);display=projection.createVirtualDisplay("EHTID",width,height,density,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,handler);return START_NOT_STICKY;}
 void createOverlay(){overlay=new LinearLayout(this);overlay.setOrientation(1);overlay.setPadding(12,8,12,8);overlay.setBackgroundColor(0xe51c1732);LinearLayout buttons=new LinearLayout(this);Button translate=new Button(this);translate.setText("Перевести");buttons.addView(translate);Button repeat=new Button(this);repeat.setText("Авто: выкл");buttons.addView(repeat);Button close=new Button(this);close.setText("X");buttons.addView(close);overlay.addView(buttons);output=new TextView(this);output.setTextColor(-1);output.setTextSize(15);output.setText("Нажми Перевести");output.setMaxLines(14);overlay.addView(output);WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,android.graphics.PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;p.x=0;p.y=100;wm.addView(overlay,p);translate.setOnClickListener(v->capture());repeat.setOnClickListener(v->{auto=!auto;repeat.setText(auto?"Авто: вкл":"Авто: выкл");if(auto)autoLoop();});close.setOnClickListener(v->stopSelf());}
 void autoLoop(){if(!auto)return;capture();handler.postDelayed(this::autoLoop,4500);}
 void capture(){if(busy||reader==null)return;busy=true;overlay.setVisibility(View.INVISIBLE);handler.postDelayed(()->{Image img=reader.acquireLatestImage();overlay.setVisibility(View.VISIBLE);if(img==null){busy=false;return;}try{Image.Plane plane=img.getPlanes()[0];ByteBuffer buf=plane.getBuffer();int stride=plane.getRowStride(),pixel=plane.getPixelStride();Bitmap padded=Bitmap.createBitmap(width+(stride-pixel*width)/pixel,height,Bitmap.Config.ARGB_8888);padded.copyPixelsFromBuffer(buf);Bitmap bmp=Bitmap.createBitmap(padded,0,0,width,height);padded.recycle();recognize(bmp);}catch(Exception e){output.setText("Ошибка захвата: "+e.getMessage());busy=false;}finally{img.close();}},280);}
 void recognize(Bitmap bmp){List<com.google.android.gms.tasks.Task<com.google.mlkit.vision.text.Text>> tasks=new ArrayList<>();InputImage input=InputImage.fromBitmap(bmp,0);for(TextRecognizer r:recognizers)tasks.add(r.process(input));com.google.android.gms.tasks.Tasks.whenAllComplete(tasks).addOnSuccessListener(done->{String best="";int score=0;for(com.google.android.gms.tasks.Task<com.google.mlkit.vision.text.Text> t:tasks){if(t.isSuccessful()){String s=t.getResult().getText().trim();int count=s.replaceAll("\\s","").length();if(count>score){score=count;best=s;}}}bmp.recycle();if(best.isEmpty()){output.setText("Текст не найден");busy=false;}else identify(best);}).addOnFailureListener(e->{bmp.recycle();busy=false;output.setText("OCR: "+e.getMessage());});}
 void identify(String text){LanguageIdentifier lid=LanguageIdentification.getClient();lid.identifyLanguage(text).addOnCompleteListener(t->{lid.close();String lang=t.isSuccessful()?t.getResult():"und";if(lang.equals("und")){output.setText("Язык не определён:\n"+text);busy=false;return;}if(lang.equals("ru")){output.setText(text);busy=false;return;}String source=TranslateLanguage.fromLanguageTag(lang);if(source==null){output.setText("Язык "+lang+" не поддерживается:\n"+text);busy=false;return;}translate(text,source);});}
 void translate(String text,String source){if(translator==null||!source.equals(translatorLang)){if(translator!=null)translator.close();translatorLang=source;translator=Translation.getClient(new TranslatorOptions.Builder().setSourceLanguage(source).setTargetLanguage(TranslateLanguage.RUSSIAN).build());}Translator current=translator;output.setText("Загружаю модель "+source+" → ru…");current.downloadModelIfNeeded().addOnSuccessListener(v->current.translate(text).addOnSuccessListener(s->{output.setText(s);busy=false;}).addOnFailureListener(e->{output.setText("Перевод: "+e.getMessage());busy=false;})).addOnFailureListener(e->{output.setText("Не удалось скачать модель: "+e.getMessage());busy=false;});}
 @Override public void onDestroy(){auto=false;handler.removeCallbacksAndMessages(null);if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();if(overlay!=null)wm.removeView(overlay);for(TextRecognizer r:recognizers)r.close();if(translator!=null)translator.close();super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}